#!/usr/bin/env node
// Runs the prebuilt {{name}} binary for this platform (installed as an optional dependency).
// Generated by anything-anything.
"use strict";
const { spawnSync } = require("node:child_process");
const fs = require("node:fs");

const pkg = `{{npm}}-${process.platform}-${process.arch}`;
const exe = process.platform === "win32" ? "{{name}}.exe" : "{{name}}";
let bin;
try {
  bin = require.resolve(`${pkg}/bin/${exe}`);
} catch {
  console.error(
    `{{name}}: no prebuilt binary for ${process.platform}-${process.arch} (${pkg} isn't installed).\n` +
      "Reinstall without --omit=optional, or build it: cargo install {{name}}",
  );
  process.exit(1);
}
if (process.platform !== "win32") {
  try {
    fs.chmodSync(bin, 0o755);
  } catch {
    // spawnSync reports EACCES if it still isn't executable
  }
}
const run = spawnSync(bin, process.argv.slice(2), { stdio: "inherit" });
if (run.error) {
  console.error(`{{name}}: ${run.error.message}`);
  process.exit(1);
}
process.exit(run.status ?? 1);
